<script lang="ts">
	import { afterNavigate } from '$app/navigation'; import { apiData } from '$lib/api'; import AssetManagementShell from '$lib/components/AssetManagementShell.svelte';
	type Item={id:number;code:string;name:string}; const labels:Record<string,string>={departments:'Departments','employee-groups':'Groups',positions:'Positions','employment-types':'Employment types',branches:'Branches'}; let resource=$state(''); const title=$derived(labels[resource]??'Employee masters'); const endpoint=$derived('/v1/'+resource);
	let items=$state<Item[]>([]),code=$state(''),name=$state(''),editing=$state<Item|null>(null),message=$state(''),canManage=$state(false);
	async function load(){const response=await fetch(endpoint);if(!response.ok){message='Unable to load master data.';return;}items=await apiData<Item[]>(response);} function reset(){editing=null;code='';name='';} async function save(){const response=await fetch(endpoint+(editing?'/'+editing.id:''),{method:editing?'PATCH':'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code,name})});if(!response.ok){message='Unable to save this item.';return;}reset();await load();} async function remove(item:Item){if(!confirm('Delete '+item.name+'?'))return;const response=await fetch(endpoint+'/'+item.id,{method:'DELETE'});if(!response.ok){message='This item is in use or could not be deleted.';return;}await load();} afterNavigate(()=>{resource=window.location.pathname.split('/').at(-1) ?? ''; reset(); void (async()=>{const response=await fetch('/v1/auth/session');if(response.ok){const session=await apiData<{user:{role:string}}>(response);canManage=session.user.role==='system_administrator'||session.user.role==='business_administrator';}await load();})();});
</script>
<AssetManagementShell {title} active=""><div class="heading"><p>CONFIGURATION</p><h1>{title}</h1></div><section>{#if canManage}<form onsubmit={(event)=>{event.preventDefault();void save();}}><input bind:value={code} placeholder="Code" required maxlength="64"/><input bind:value={name} placeholder="Name" required maxlength="128"/><button type="submit">{editing?'Save':'Add'}</button>{#if editing}<button type="button" onclick={reset}>Cancel</button>{/if}</form>{/if}{#if message}<p>{message}</p>{/if}<table><thead><tr><th>Code</th><th>Name</th>{#if canManage}<th></th>{/if}</tr></thead><tbody>{#each items as item}<tr><td>{item.code}</td><td>{item.name}</td>{#if canManage}<td><button class="edit" type="button" onclick={()=>{editing=item;code=item.code;name=item.name;}}>Edit</button><button class="danger" type="button" onclick={()=>void remove(item)}>Delete</button></td>{/if}</tr>{/each}</tbody></table></section></AssetManagementShell>
<style>.heading{margin-bottom:24px}.heading p{color:#1abb9c;font-size:11px;font-weight:700}.heading h1{margin:4px 0;font-size:30px}section{padding:20px;background:var(--surface);border:1px solid var(--border);border-radius:6px}form{display:flex;gap:10px;margin-bottom:20px}input{padding:8px;border:1px solid var(--border);border-radius:4px;background:var(--surface);color:var(--text)}button{padding:8px 12px;background:#1abb9c;color:#fff;border:1px solid #169f85;border-radius:4px}.edit{background:#066fd1;border-color:#066fd1}.danger{margin-left:6px;background:#d63939;border-color:#c92f2f}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid var(--border);text-align:left}</style>
